package com.crestlinebank.dao;
import com.crestlinebank.config.Database;
import com.crestlinebank.model.Staff;
import com.crestlinebank.util.PasswordUtil;
import java.math.BigDecimal;
import java.sql.*;
import java.util.*;

public class StaffDao {
 public List<Object[]> all() throws SQLException {
  List<Object[]> out=new ArrayList<>(); String q="SELECT id,full_name,email,role,salary,max_loan_approval,status,joined_on FROM staff ORDER BY id DESC";
  try(Connection c=Database.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery(q)){while(r.next())out.add(new Object[]{r.getInt(1),r.getString(2),r.getString(3),r.getString(4),r.getBigDecimal(5),r.getBigDecimal(6),r.getString(7),r.getDate(8)});} return out;
 }
 public void hire(String name,String email,String password,String role,BigDecimal salary,BigDecimal max) throws SQLException {
  if(name==null||name.isBlank()||email==null||!email.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")||password==null||password.length()<8)throw new IllegalArgumentException("Enter name, valid email and a password of at least 8 characters.");
  validate(role,salary,max); String q="INSERT INTO staff(full_name,email,password_hash,role,salary,max_loan_approval) VALUES(?,?,?,?,?,?)";
  try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,name.trim());p.setString(2,email.trim().toLowerCase(Locale.ROOT));p.setString(3,PasswordUtil.hash(password));p.setString(4,role);p.setBigDecimal(5,salary);p.setBigDecimal(6,max);p.executeUpdate();} try(Connection c=Database.getConnection();PreparedStatement h=c.prepareStatement("INSERT INTO staff_salary_history(staff_id,salary) SELECT id,salary FROM staff WHERE email=?")){h.setString(1,email.trim().toLowerCase(Locale.ROOT));h.executeUpdate();}
 }
 public void update(int id,String role,BigDecimal salary,BigDecimal max) throws SQLException {validate(role,salary,max);try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("UPDATE staff SET role=?,salary=?,max_loan_approval=? WHERE id=?")){p.setString(1,role);p.setBigDecimal(2,salary);p.setBigDecimal(3,max);p.setInt(4,id);if(p.executeUpdate()!=1)throw new SQLException("Staff member not found.");} try(Connection c=Database.getConnection();PreparedStatement h=c.prepareStatement("INSERT INTO staff_salary_history(staff_id,salary) VALUES(?,?)")){h.setInt(1,id);h.setBigDecimal(2,salary);h.executeUpdate();}}
 public void setStatus(int id,String status,String reason) throws SQLException {if(!Set.of("ACTIVE","INACTIVE").contains(status))throw new IllegalArgumentException("Invalid employment status.");if("INACTIVE".equals(status)&&(reason==null||reason.trim().length()<4))throw new IllegalArgumentException("Enter a reason before removing/deactivating a staff member.");try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("UPDATE staff SET status=?,employment_note=? WHERE id=?")){p.setString(1,status);p.setString(2,reason==null?"":reason.trim());p.setInt(3,id);p.executeUpdate();}}
 public Optional<Staff> login(String email,String password) throws SQLException {String q="SELECT id,full_name,email,role,salary,max_loan_approval,password_hash FROM staff WHERE email=? AND status='ACTIVE'";try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,email.trim().toLowerCase(Locale.ROOT));try(ResultSet r=p.executeQuery()){if(!r.next()||!PasswordUtil.matches(password,r.getString(7)))return Optional.empty();Staff s=new Staff(r.getInt(1),r.getString(2),r.getString(3),r.getString(4),r.getBigDecimal(5),r.getBigDecimal(6));log(s.id(),"LOGIN","Staff signed in");return Optional.of(s);}}}

 public void assignTask(int staffId,String title,String details)throws SQLException{if(title==null||title.isBlank())throw new IllegalArgumentException("Enter a task title.");try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO staff_tasks(staff_id,title,details) VALUES(?,?,?)")){p.setInt(1,staffId);p.setString(2,title.trim());p.setString(3,details==null?"":details.trim());p.executeUpdate();}}
 public List<Object[]> tasks(int staffId)throws SQLException{List<Object[]> out=new ArrayList<>();try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT id,title,details,status,assigned_at FROM staff_tasks WHERE staff_id=? ORDER BY status,assigned_at DESC")){p.setInt(1,staffId);try(ResultSet r=p.executeQuery()){while(r.next())out.add(new Object[]{r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getTimestamp(5)});}}return out;}
 public void completeTask(int staffId,long taskId)throws SQLException{try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("UPDATE staff_tasks SET status='COMPLETED',completed_at=CURRENT_TIMESTAMP WHERE id=? AND staff_id=? AND status='PENDING'")){p.setLong(1,taskId);p.setInt(2,staffId);if(p.executeUpdate()!=1)throw new SQLException("Pending task not found.");}log(staffId,"TASK_COMPLETED","Task #"+taskId);}

 public List<Object[]> pendingLoans() throws SQLException {List<Object[]> out=new ArrayList<>();String q="SELECT l.id,c.full_name,l.principal,l.status FROM loans l JOIN customers c ON c.id=l.customer_id WHERE l.status='PENDING' ORDER BY l.created_at";try(Connection c=Database.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery(q)){while(r.next())out.add(new Object[]{r.getInt(1),r.getString(2),r.getBigDecimal(3),r.getString(4)});}return out;}
 public void decideLoan(int staffId,int loanId,String decision) throws SQLException {if(!Set.of("APPROVED","REJECTED").contains(decision))throw new IllegalArgumentException("Invalid decision.");try(Connection c=Database.getConnection()){c.setAutoCommit(false);BigDecimal max;try(PreparedStatement p=c.prepareStatement("SELECT max_loan_approval FROM staff WHERE id=? AND status='ACTIVE' FOR UPDATE")){p.setInt(1,staffId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Staff account inactive.");max=r.getBigDecimal(1);}}BigDecimal principal;try(PreparedStatement p=c.prepareStatement("SELECT principal FROM loans WHERE id=? AND status='PENDING' FOR UPDATE")){p.setInt(1,loanId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Pending loan not found.");principal=r.getBigDecimal(1);}}if("APPROVED".equals(decision)&&principal.compareTo(max)>0)throw new SQLException("This loan exceeds your approval authority. Forward it to the Admin.");BigDecimal interest=BigDecimal.ZERO;if("APPROVED".equals(decision)){BigDecimal rate;int months;try(PreparedStatement d=c.prepareStatement("SELECT annual_rate,tenure_months FROM loans WHERE id=?")){d.setInt(1,loanId);try(ResultSet z=d.executeQuery()){z.next();rate=z.getBigDecimal(1);months=z.getInt(2);}}double mr=rate.doubleValue()/1200.0,pow=Math.pow(1+mr,months);double emi=mr==0?principal.doubleValue()/months:principal.doubleValue()*mr*pow/(pow-1);interest=BigDecimal.valueOf(emi*months).subtract(principal).max(BigDecimal.ZERO).setScale(2,java.math.RoundingMode.HALF_UP);}try(PreparedStatement p=c.prepareStatement("UPDATE loans SET status=?,total_interest=?,next_due_date=CASE WHEN ?='APPROVED' THEN DATE_ADD(CURRENT_DATE,INTERVAL 1 MONTH) ELSE NULL END WHERE id=? AND status='PENDING'")){p.setString(1,decision);p.setBigDecimal(2,interest);p.setString(3,decision);p.setInt(4,loanId);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("INSERT INTO staff_activity_log(staff_id,action,details) VALUES(?,?,?)")){p.setInt(1,staffId);p.setString(2,"LOAN_"+decision);p.setString(3,"Loan #"+loanId+"; amount ₹"+principal);p.executeUpdate();}c.commit();}}
 public void log(int id,String action,String details)throws SQLException{try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO staff_activity_log(staff_id,action,details) VALUES(?,?,?)")){p.setInt(1,id);p.setString(2,action);p.setString(3,details);p.executeUpdate();}}
 private void validate(String role,BigDecimal salary,BigDecimal max){if(!Set.of("CASHIER","LOAN_OFFICER","CUSTOMER_SUPPORT","ACCOUNT_OFFICER","BRANCH_MANAGER","AUDITOR").contains(role))throw new IllegalArgumentException("Choose a valid staff role.");if(salary==null||salary.signum()<0||max==null||max.signum()<0)throw new IllegalArgumentException("Salary and approval limit cannot be negative.");}
}
